INSERT INTO changelog (title, body, created_at) VALUES ('Розбір у Стратегію знову працює', 'Вставка витяжки або розмови в «Стратегія → Вставити витяжку» падала з помилкою «SQLite3 can only bind…» — модель інколи віддає списки замість тексту. Тепер усе зводиться до тексту (як раніше виправили для продуктів). Устав той самий текст ще раз.', datetime('now'));
